-- 042: Prevención de LC/FT/FPADM en las auditorías operativas y especiales.
--
-- Normativa: Providencia SUDEASEG SAA-01-0536-2024 (29/08/2024, Gaceta Oficial Extraordinaria N° 6.835 del 03/09/2024), «Normas sobre
-- Administración de Riesgos de Legitimación de Capitales, Financiamiento al Terrorismo, Financiamiento de la
-- Proliferación de Armas de Destrucción Masiva y otros Ilícitos en la Actividad Aseguradora» (derogó la Providencia
-- SAA-08-004-2021), y Ley Orgánica contra la Delincuencia Organizada y Financiamiento al Terrorismo (registro de
-- sujetos obligados y de oficiales de cumplimiento ante la ONCDOFT; reportes a la UNIF).
-- Las referencias se citan sin números de artículo: el Oficial de Cumplimiento debe validarlas y precisarlas en
-- Reglas de los motores › Normativa SUDEASEG (cambio con doble control).
--
-- 1. El tema «lcft» del catálogo se divide en siete temas (conozca a su cliente; PEP y listas restrictivas;
--    reporte de actividades sospechosas; conservación de registros; SIAR y Oficial de Cumplimiento; capacitación
--    y código de conducta; conozca a su empleado, intermediario y proveedor).
-- 2. Nueva cédula cuestionario «Prevención LC/FT/FPADM» (kind LCFT, línea General): 8 bloques ponderados y
--    26 preguntas, calificada como LOPCYMAT (Sí = 1, No = 0, N/A no cuenta; índice = suma de peso x cumplimiento).
--    Propuesta de Contraloría a validar por el Oficial de Cumplimiento.
-- 3. El Auditor que generó un Informe Ejecutivo o de Documentación puede editar su conclusión (eventos en la bitácora).

ALTER TABLE engagement.worksheets DROP CONSTRAINT IF EXISTS worksheets_kind_check;
ALTER TABLE engagement.worksheets ADD CONSTRAINT worksheets_kind_check CHECK (kind IN ('SUSCRIPCION', 'RECLAMO', 'SISTEMAS', 'CXP', 'CXC', 'ADMIN', 'CARTELERA', 'ADS', 'LOPCYMAT', 'SERV_SUC', 'TI_SUC', 'LCFT'));

ALTER TABLE engagement.financial_templates DROP CONSTRAINT IF EXISTS financial_templates_kind_line_check;
ALTER TABLE engagement.financial_templates ADD CONSTRAINT financial_templates_kind_line_check CHECK (
    (kind = 'TRANSVERSAL' AND line IS NULL)
    OR (kind IN ('SUSCRIPCION', 'RECLAMO') AND line IN ('AUTO', 'PATRIMONIAL', 'PERSONAL'))
    OR (kind IN ('CXP', 'CXC', 'ADMIN', 'CARTELERA', 'ADS', 'LOPCYMAT', 'SERV_SUC', 'TI_SUC', 'LCFT') AND line = 'GENERAL'));

