ON CONFLICT (code) DO NOTHING;

INSERT INTO engagement.financial_criteria (template_code, source_id, section, subsection, criterion_text, sort_order, excel_row, metadata) VALUES
    ('AUD_LCFT', 'LCFT-1.1', 'I. Estructura del SIAR y Oficial de Cumplimiento', NULL, '¿La empresa tiene designado un Oficial de Cumplimiento y un Responsable de Cumplimiento, notificados a la SUDEASEG e inscritos ante la ONCDOFT, y el personal de la unidad auditada sabe quién es y cómo contactarlo?', 1, 1, '{"block": "1", "block_title": "I. Estructura del SIAR y Oficial de Cumplimiento", "block_weight": 0.15, "number": "1.1"}'::jsonb),
    ('AUD_LCFT', 'LCFT-1.2', 'I. Estructura del SIAR y Oficial de Cumplimiento', NULL, '¿Existe una Unidad de Administración de Riesgos de legitimación de capitales con funciones, recursos y dependencia formalizadas en la estructura del Sistema Integral de Administración de Riesgos (SIAR)?', 2, 2, '{"block": "1", "block_title": "I. Estructura del SIAR y Oficial de Cumplimiento", "block_weight": 0.15, "number": "1.2"}'::jsonb),
    ('AUD_LCFT', 'LCFT-1.3', 'I. Estructura del SIAR y Oficial de Cumplimiento', NULL, '¿La Junta Directiva aprueba y supervisa el SIAR y recibe informes periódicos del Oficial de Cumplimiento sobre la gestión de riesgos de legitimación de capitales?', 3, 3, '{"block": "1", "block_title": "I. Estructura del SIAR y Oficial de Cumplimiento", "block_weight": 0.15, "number": "1.3"}'::jsonb),
    ('AUD_LCFT', 'LCFT-2.1', 'II. Manual, Plan Operativo Anual y autoevaluación de riesgos', NULL, '¿El Manual de Políticas y Procedimientos de administración de riesgos de legitimación de capitales está aprobado por la Junta Directiva, vigente, remitido a la SUDEASEG y disponible para el personal de la unidad?', 4, 4, '{"block": "2", "block_title": "II. Manual, Plan Operativo Anual y autoevaluación de riesgos", "block_weight": 0.1, "number": "2.1"}'::jsonb),
    ('AUD_LCFT', 'LCFT-2.2', 'II. Manual, Plan Operativo Anual y autoevaluación de riesgos', NULL, '¿El Plan Operativo Anual del SIAR está aprobado, remitido a la SUDEASEG en el plazo establecido y se le hace seguimiento documentado?', 5, 5, '{"block": "2", "block_title": "II. Manual, Plan Operativo Anual y autoevaluación de riesgos", "block_weight": 0.1, "number": "2.2"}'::jsonb),
    ('AUD_LCFT', 'LCFT-2.3', 'II. Manual, Plan Operativo Anual y autoevaluación de riesgos', NULL, '¿La autoevaluación anual de riesgos de legitimación de capitales (clientes, productos, canales y zonas geográficas) está actualizada y remitida a la SUDEASEG?', 6, 6, '{"block": "2", "block_title": "II. Manual, Plan Operativo Anual y autoevaluación de riesgos", "block_weight": 0.1, "number": "2.3"}'::jsonb),
    ('AUD_LCFT', 'LCFT-3.1', 'III. Conozca a su cliente y debida diligencia', NULL, 'En la muestra de expedientes, ¿la identificación del cliente (cédula o RIF vigente y datos verificados) está completa antes de emitir la póliza o pagar el siniestro?', 7, 7, '{"block": "3", "block_title": "III. Conozca a su cliente y debida diligencia", "block_weight": 0.2, "number": "3.1"}'::jsonb),
    ('AUD_LCFT', 'LCFT-3.2', 'III. Conozca a su cliente y debida diligencia', NULL, '¿Se aplica la política conozca a su cliente con formulario de debida diligencia firmado, actividad económica, perfil del cliente y origen de fondos declarado?', 8, 8, '{"block": "3", "block_title": "III. Conozca a su cliente y debida diligencia", "block_weight": 0.2, "number": "3.2"}'::jsonb),
    ('AUD_LCFT', 'LCFT-3.3', 'III. Conozca a su cliente y debida diligencia', NULL, '¿Se aplica debida diligencia ampliada a los clientes de mayor riesgo (montos altos, pagos en efectivo, terceros pagadores o beneficiarios no relacionados)?', 9, 9, '{"block": "3", "block_title": "III. Conozca a su cliente y debida diligencia", "block_weight": 0.2, "number": "3.3"}'::jsonb),
    ('AUD_LCFT', 'LCFT-3.4', 'III. Conozca a su cliente y debida diligencia', NULL, '¿Se actualiza periódicamente la información de debida diligencia de los clientes según su nivel de riesgo?', 10, 10, '{"block": "3", "block_title": "III. Conozca a su cliente y debida diligencia", "block_weight": 0.2, "number": "3.4"}'::jsonb),
    ('AUD_LCFT', 'LCFT-3.5', 'III. Conozca a su cliente y debida diligencia', NULL, '¿El sistema impide emitir pólizas o pagar indemnizaciones cuando faltan los datos y recaudos obligatorios de identificación del cliente?', 11, 11, '{"block": "3", "block_title": "III. Conozca a su cliente y debida diligencia", "block_weight": 0.2, "number": "3.5"}'::jsonb),
    ('AUD_LCFT', 'LCFT-4.1', 'IV. Personas expuestas políticamente (PEP) y listas restrictivas', NULL, '¿Se identifica si el cliente, beneficiario o tercero pagador es una persona expuesta políticamente (PEP) y su relación con la operación queda documentada?', 12, 12, '{"block": "4", "block_title": "IV. Personas expuestas políticamente (PEP) y listas restrictivas", "block_weight": 0.1, "number": "4.1"}'::jsonb),
    ('AUD_LCFT', 'LCFT-4.2', 'IV. Personas expuestas políticamente (PEP) y listas restrictivas', NULL, '¿Las relaciones con PEP requieren aprobación de un nivel gerencial y debida diligencia ampliada?', 13, 13, '{"block": "4", "block_title": "IV. Personas expuestas políticamente (PEP) y listas restrictivas", "block_weight": 0.1, "number": "4.2"}'::jsonb),
    ('AUD_LCFT', 'LCFT-4.3', 'IV. Personas expuestas políticamente (PEP) y listas restrictivas', NULL, '¿Se verifica a clientes, beneficiarios e intermediarios contra las listas restrictivas y de sanciones (Consejo de Seguridad de la ONU y demás listas oficiales) antes de contratar o pagar, conservando la evidencia de la consulta?', 14, 14, '{"block": "4", "block_title": "IV. Personas expuestas políticamente (PEP) y listas restrictivas", "block_weight": 0.1, "number": "4.3"}'::jsonb),
    ('AUD_LCFT', 'LCFT-5.1', 'V. Detección y reporte de actividades sospechosas', NULL, '¿El personal de la unidad conoce las señales de alerta de operaciones inusuales propias de la actividad aseguradora (rescates o cancelaciones anticipadas, sobrepagos, primas en efectivo, cambios de beneficiario)?', 15, 15, '{"block": "5", "block_title": "V. Detección y reporte de actividades sospechosas", "block_weight": 0.15, "number": "5.1"}'::jsonb),
    ('AUD_LCFT', 'LCFT-5.2', 'V. Detección y reporte de actividades sospechosas', NULL, '¿Existe un canal interno documentado para reportar operaciones inusuales al Oficial de Cumplimiento y se usa (registro de los reportes internos)?', 16, 16, '{"block": "5", "block_title": "V. Detección y reporte de actividades sospechosas", "block_weight": 0.15, "number": "5.2"}'::jsonb),
    ('AUD_LCFT', 'LCFT-5.3', 'V. Detección y reporte de actividades sospechosas', NULL, '¿El Oficial de Cumplimiento analiza las operaciones inusuales y reporta las actividades sospechosas a la Unidad Nacional de Inteligencia Financiera (UNIF), dejando constancia del análisis?', 17, 17, '{"block": "5", "block_title": "V. Detección y reporte de actividades sospechosas", "block_weight": 0.15, "number": "5.3"}'::jsonb),
    ('AUD_LCFT', 'LCFT-5.4', 'V. Detección y reporte de actividades sospechosas', NULL, '¿Se resguarda la confidencialidad de los reportes de actividades sospechosas, sin informar al cliente que su operación fue reportada?', 18, 18, '{"block": "5", "block_title": "V. Detección y reporte de actividades sospechosas", "block_weight": 0.15, "number": "5.4"}'::jsonb),
    ('AUD_LCFT', 'LCFT-6.1', 'VI. Conservación de registros', NULL, '¿Se conservan los registros de las operaciones y los expedientes de clientes (identificación, debida diligencia y soportes) durante el plazo exigido por la normativa vigente, en forma íntegra y recuperable?', 19, 19, '{"block": "6", "block_title": "VI. Conservación de registros", "block_weight": 0.1, "number": "6.1"}'::jsonb),
    ('AUD_LCFT', 'LCFT-6.2', 'VI. Conservación de registros', NULL, '¿La conservación de registros permite reconstruir cada operación (póliza, prima, siniestro y pago) y atender con prontitud los requerimientos de la SUDEASEG y de las autoridades competentes?', 20, 20, '{"block": "6", "block_title": "VI. Conservación de registros", "block_weight": 0.1, "number": "6.2"}'::jsonb),
    ('AUD_LCFT', 'LCFT-7.1', 'VII. Capacitación en prevención y código de conducta', NULL, '¿El personal de la unidad recibió en el último año la capacitación en prevención de legitimación de capitales del programa anual de capacitación, con constancia de asistencia y evaluación?', 21, 21, '{"block": "7", "block_title": "VII. Capacitación en prevención y código de conducta", "block_weight": 0.1, "number": "7.1"}'::jsonb),
    ('AUD_LCFT', 'LCFT-7.2', 'VII. Capacitación en prevención y código de conducta', NULL, '¿El personal nuevo recibe inducción en prevención de legitimación de capitales antes de atender clientes?', 22, 22, '{"block": "7", "block_title": "VII. Capacitación en prevención y código de conducta", "block_weight": 0.1, "number": "7.2"}'::jsonb),
    ('AUD_LCFT', 'LCFT-7.3', 'VII. Capacitación en prevención y código de conducta', NULL, '¿El código de conducta en materia de prevención está aprobado, divulgado y firmado por todo el personal de la unidad?', 23, 23, '{"block": "7", "block_title": "VII. Capacitación en prevención y código de conducta", "block_weight": 0.1, "number": "7.3"}'::jsonb),
    ('AUD_LCFT', 'LCFT-8.1', 'VIII. Conozca a su empleado, intermediario y proveedor', NULL, '¿Se aplica la política conozca a su empleado (verificación de antecedentes al ingreso y seguimiento de cambios en el perfil económico del personal)?', 24, 24, '{"block": "8", "block_title": "VIII. Conozca a su empleado, intermediario y proveedor", "block_weight": 0.1, "number": "8.1"}'::jsonb),
    ('AUD_LCFT', 'LCFT-8.2', 'VIII. Conozca a su empleado, intermediario y proveedor', NULL, '¿Se aplica la política conozca a su intermediario a los productores de seguros (corredores y agentes) con los que opera la unidad, verificando su autorización vigente ante la SUDEASEG?', 25, 25, '{"block": "8", "block_title": "VIII. Conozca a su empleado, intermediario y proveedor", "block_weight": 0.1, "number": "8.2"}'::jsonb),
    ('AUD_LCFT', 'LCFT-8.3', 'VIII. Conozca a su empleado, intermediario y proveedor', NULL, '¿Se aplica la política conozca a su proveedor (talleres, clínicas, peritos y demás proveedores de servicios de siniestros) con verificación de identidad y de listas restrictivas?', 26, 26, '{"block": "8", "block_title": "VIII. Conozca a su empleado, intermediario y proveedor", "block_weight": 0.1, "number": "8.3"}'::jsonb)
ON CONFLICT (template_code, source_id) DO NOTHING;

-- Catálogo normativo: el tema «lcft» se actualiza a la norma vigente y se agregan seis temas nuevos.
INSERT INTO engagement.regulatory_catalog (topic, label, keywords, criteria, cause, effect, recommendation, sort_order, active) VALUES
    ('lcft', 'conozca a su cliente y debida diligencia (LC/FT/FPADM)', ARRAY['conozca a su cliente', 'debida diligencia', 'identificac', 'rif', 'cedula', 'c.i', 'huella', 'verificacion de datos', 'origen de fondos', 'perfil del cliente', 'recaudos obligatorios']::text[],
     'Providencia SUDEASEG SAA-01-0536-2024 (G.O. Ext. N° 6.835 del 03/09/2024) y Ley Orgánica contra la Delincuencia Organizada y Financiamiento al Terrorismo: identificación, verificación y debida diligencia del cliente (simplificada, estándar o ampliada según su riesgo) antes de establecer la relación, emitir la póliza o pagar la indemnización.',
     'La política conozca a su cliente no se aplica de forma completa: faltan controles que impidan emitir o pagar sin los datos y documentos de identificación exigidos y la debida diligencia no se ajusta al riesgo del cliente.',
     'Operar con clientes no identificados o sin debida diligencia expone a la empresa a ser utilizada para legitimar capitales, a sanciones de la SUDEASEG y a responsabilidad penal y reputacional.',
     'Bloquear en el sistema la emisión y el pago sin los datos y documentos de identificación obligatorios, completar la debida diligencia de los clientes observados (ampliada para los de mayor riesgo) y actualizarla periódicamente.', 30, TRUE)
ON CONFLICT (topic) DO UPDATE SET label = EXCLUDED.label, keywords = EXCLUDED.keywords, criteria = EXCLUDED.criteria, cause = EXCLUDED.cause,
    effect = EXCLUDED.effect, recommendation = EXCLUDED.recommendation, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO engagement.regulatory_catalog (topic, label, keywords, criteria, cause, effect, recommendation, sort_order, active) VALUES
    ('lcft_pep', 'personas expuestas políticamente y listas restrictivas', ARRAY['expuesta politicamente', 'expuestas politicamente', 'pep', 'listas restrictivas', 'listas de sanciones', 'consejo de seguridad', 'onu']::text[],
     'Providencia SUDEASEG SAA-01-0536-2024 (G.O. Ext. N° 6.835 del 03/09/2024) y Ley Orgánica contra la Delincuencia Organizada y Financiamiento al Terrorismo: identificación de personas expuestas políticamente con aprobación gerencial y debida diligencia ampliada, y verificación contra las listas oficiales de sanciones (Consejo de Seguridad de la ONU y demás listas) antes de contratar o pagar.',
     'No existe una verificación sistemática de PEP y de listas restrictivas en la contratación y el pago, ni se conserva la evidencia de las consultas.',
     'Mantener relaciones u operaciones con PEP sin controles reforzados o con personas incluidas en listas de sanciones expone a la empresa a sanciones, al congelamiento de operaciones y a un grave daño reputacional.',
     'Automatizar la consulta de PEP y de listas restrictivas en la emisión, el pago y el registro de intermediarios y proveedores, exigir aprobación gerencial para las relaciones con PEP y conservar la evidencia de cada consulta.', 31, TRUE)
ON CONFLICT (topic) DO UPDATE SET label = EXCLUDED.label, keywords = EXCLUDED.keywords, criteria = EXCLUDED.criteria, cause = EXCLUDED.cause,
    effect = EXCLUDED.effect, recommendation = EXCLUDED.recommendation, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO engagement.regulatory_catalog (topic, label, keywords, criteria, cause, effect, recommendation, sort_order, active) VALUES
    ('lcft_reporte', 'detección y reporte de actividades sospechosas', ARRAY['actividad sospechosa', 'actividades sospechosas', 'operaciones inusuales', 'operacion inusual', 'senales de alerta', 'unif', 'inteligencia financiera', 'reporte interno', 'reportes internos']::text[],
     'Providencia SUDEASEG SAA-01-0536-2024 (G.O. Ext. N° 6.835 del 03/09/2024) y Ley Orgánica contra la Delincuencia Organizada y Financiamiento al Terrorismo: detección de operaciones inusuales, análisis por el Oficial de Cumplimiento y reporte de actividades sospechosas a la Unidad Nacional de Inteligencia Financiera (UNIF), con confidencialidad.',
     'El personal no identifica las señales de alerta propias de la actividad aseguradora o no existe un canal interno documentado para reportar operaciones inusuales al Oficial de Cumplimiento.',
     'Las operaciones sospechosas no detectadas o no reportadas exponen a la empresa y a sus funcionarios a sanciones administrativas y penales y a ser usada para legitimar capitales.',
     'Divulgar las señales de alerta del sector asegurador, formalizar el canal de reporte interno al Oficial de Cumplimiento con registro de cada reporte y documentar el análisis y el reporte a la UNIF, resguardando su confidencialidad.', 32, TRUE)
ON CONFLICT (topic) DO UPDATE SET label = EXCLUDED.label, keywords = EXCLUDED.keywords, criteria = EXCLUDED.criteria, cause = EXCLUDED.cause,
    effect = EXCLUDED.effect, recommendation = EXCLUDED.recommendation, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO engagement.regulatory_catalog (topic, label, keywords, criteria, cause, effect, recommendation, sort_order, active) VALUES
    ('lcft_registros', 'conservación de registros (LC/FT/FPADM)', ARRAY['conservacion de registros', 'conservan los registros', 'registros de las operaciones', 'reconstruir cada operacion']::text[],
     'Providencia SUDEASEG SAA-01-0536-2024 (G.O. Ext. N° 6.835 del 03/09/2024) y Ley Orgánica contra la Delincuencia Organizada y Financiamiento al Terrorismo: conservación íntegra y recuperable de los registros de las operaciones y de los expedientes de los clientes durante el plazo exigido por la normativa vigente.',
     'No existe un procedimiento de conservación y recuperación de los registros y expedientes de clientes que asegure su integridad durante el plazo exigido.',
     'Sin registros completos la empresa no puede reconstruir las operaciones ni atender los requerimientos de la SUDEASEG y de las autoridades, lo que constituye un incumplimiento sancionable.',
     'Definir y aplicar un procedimiento de conservación de registros (plazo, medio, custodia y recuperación), digitalizar los expedientes y probar periódicamente su recuperación.', 33, TRUE)
ON CONFLICT (topic) DO UPDATE SET label = EXCLUDED.label, keywords = EXCLUDED.keywords, criteria = EXCLUDED.criteria, cause = EXCLUDED.cause,
    effect = EXCLUDED.effect, recommendation = EXCLUDED.recommendation, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO engagement.regulatory_catalog (topic, label, keywords, criteria, cause, effect, recommendation, sort_order, active) VALUES
    ('lcft_siar', 'sistema integral de administración de riesgos de LC/FT/FPADM y Oficial de Cumplimiento', ARRAY['oficial de cumplimiento', 'responsable de cumplimiento', 'siar', 'sistema integral de administracion de riesgos', 'unidad de administracion de riesgos', 'plan operativo anual', 'autoevaluacion', 'manual de politicas y procedimientos', 'legitimacion de capitales', 'oncdoft', 'prevencion de lc/ft', 'politica de prevencion']::text[],
     'Providencia SUDEASEG SAA-01-0536-2024 (G.O. Ext. N° 6.835 del 03/09/2024) y Ley Orgánica contra la Delincuencia Organizada y Financiamiento al Terrorismo: Sistema Integral de Administración de Riesgos (Junta Directiva, Oficial de Cumplimiento, Unidad de Administración de Riesgos y Responsable de Cumplimiento), manual aprobado, Plan Operativo Anual y autoevaluación anual de riesgos remitidos a la SUDEASEG.',
     'La estructura del SIAR, su manual, el Plan Operativo Anual o la autoevaluación de riesgos no están formalizados, actualizados o divulgados en la unidad auditada.',
     'Sin un sistema de administración de riesgos operativo la empresa incumple la normativa de la SUDEASEG y queda expuesta a sanciones y a ser utilizada para legitimar capitales o financiar el terrorismo.',
     'Formalizar y divulgar la estructura del SIAR, mantener aprobado y vigente el manual, ejecutar y documentar el Plan Operativo Anual y la autoevaluación de riesgos, y dar seguimiento a su remisión a la SUDEASEG.', 34, TRUE)
ON CONFLICT (topic) DO UPDATE SET label = EXCLUDED.label, keywords = EXCLUDED.keywords, criteria = EXCLUDED.criteria, cause = EXCLUDED.cause,
    effect = EXCLUDED.effect, recommendation = EXCLUDED.recommendation, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO engagement.regulatory_catalog (topic, label, keywords, criteria, cause, effect, recommendation, sort_order, active) VALUES
    ('lcft_capacitacion', 'capacitación en prevención y código de conducta', ARRAY['capacitacion en prevencion', 'programa anual de capacitacion', 'induccion en prevencion', 'codigo de conducta']::text[],
     'Providencia SUDEASEG SAA-01-0536-2024 (G.O. Ext. N° 6.835 del 03/09/2024) y Ley Orgánica contra la Delincuencia Organizada y Financiamiento al Terrorismo: programa anual de capacitación en prevención de LC/FT/FPADM para todo el personal y código de conducta aprobado y divulgado.',
     'El programa anual de capacitación no alcanza a todo el personal de la unidad, no se dicta la inducción al personal nuevo o el código de conducta no está firmado por todos.',
     'Personal sin capacitación no detecta ni reporta operaciones sospechosas, lo que aumenta la exposición de la empresa a ser usada para legitimar capitales y a sanciones por incumplimiento.',
     'Cumplir el programa anual de capacitación con constancia de asistencia y evaluación, dictar la inducción al personal nuevo antes de atender clientes y obtener la firma del código de conducta de todo el personal.', 35, TRUE)
ON CONFLICT (topic) DO UPDATE SET label = EXCLUDED.label, keywords = EXCLUDED.keywords, criteria = EXCLUDED.criteria, cause = EXCLUDED.cause,
    effect = EXCLUDED.effect, recommendation = EXCLUDED.recommendation, sort_order = EXCLUDED.sort_order, updated_at = now();
INSERT INTO engagement.regulatory_catalog (topic, label, keywords, criteria, cause, effect, recommendation, sort_order, active) VALUES
    ('lcft_terceros', 'conozca a su empleado, intermediario y proveedor', ARRAY['conozca a su empleado', 'conozca a su intermediario', 'conozca a su proveedor', 'productores de seguros', 'antecedentes al ingreso']::text[],
     'Providencia SUDEASEG SAA-01-0536-2024 (G.O. Ext. N° 6.835 del 03/09/2024) y Ley Orgánica contra la Delincuencia Organizada y Financiamiento al Terrorismo: políticas conozca a su empleado, conozca a su intermediario (productores de seguros autorizados por la SUDEASEG) y conozca a su proveedor.',
     'No se aplican de forma sistemática las verificaciones de empleados, intermediarios y proveedores de servicios de siniestros.',
     'Empleados, intermediarios o proveedores no verificados pueden facilitar operaciones de legitimación de capitales o fraudes, con sanciones y pérdidas para la empresa.',
     'Aplicar y documentar la verificación de antecedentes del personal, la vigencia de la autorización de los intermediarios y la identidad y consulta en listas restrictivas de los proveedores.', 36, TRUE)
ON CONFLICT (topic) DO UPDATE SET label = EXCLUDED.label, keywords = EXCLUDED.keywords, criteria = EXCLUDED.criteria, cause = EXCLUDED.cause,
    effect = EXCLUDED.effect, recommendation = EXCLUDED.recommendation, sort_order = EXCLUDED.sort_order, updated_at = now();

-- Informe Ejecutivo y de Documentación: el Auditor autor puede editar la conclusión (queda en la bitácora).
ALTER TABLE engagement.general_report_events DROP CONSTRAINT IF EXISTS general_report_events_action_check;
ALTER TABLE engagement.general_report_events ADD CONSTRAINT general_report_events_action_check CHECK (action IN
    ('GENERATED', 'REGENERATED', 'SIGNED_SENT', 'RETURNED', 'APPROVED', 'ACKNOWLEDGED', 'CONCLUSION_EDITED', 'CONCLUSION_RESET'));
